correspondence.golden:
// trusted-label
Propagated(M, Tag) :- TrustedSource(M, Tag).
// message-label
Propagated(M, Tag) :- TransportTag(M, Tag).
// runtime-dependency
DependsOn(Mout, Min) :- Receiver(P, Min), Sender(P, Mout), Before(Min, Mout).
// label-propagation
Propagated(Mout, Tag) :- DependsOn(Mout, Min), Propagated(Min, Tag).

// three-tag-exposure
DenyReceive(P, M) :- Incoming(P, M), Propagated(M, T3), Knows(P, T1), Knows(P, T2), TagGroup(T1, Group), TagGroup(T2, Group), TagGroup(T3, Group), P != "board", T1 != T2, T1 != T3, T2 != T3.
// three-tag-two-incoming
DenyReceive(P, M) :- Incoming(P, M), Propagated(M, T2), Propagated(M, T3), Knows(P, T1), TagGroup(T1, Group), TagGroup(T2, Group), TagGroup(T3, Group), P != "board", T1 != T2, T1 != T3, T2 != T3.
// three-tag-all-incoming
DenyReceive(P, M) :- Incoming(P, M), Propagated(M, T1), Propagated(M, T2), Propagated(M, T3), TagGroup(T1, Group), TagGroup(T2, Group), TagGroup(T3, Group), P != "board", T1 != T2, T1 != T3, T2 != T3.

// runtime-dependency
DependsOn(Mout, Min) :- Receiver(P, Min), Sender(P, Mout), Before(Min, Mout).
// knowledge
Knows(P, Tag) :- Received(P, M), Propagated(M, Tag).

// audit-receipt
Audited(Tag) :- AuditReceipt(A, Tag).
// audit-progress
Audited(Tag) :- Auditor(A), Received(A, M), Propagated(M, Tag).
// finished
Finished(Group) :- AuditGoal(Group, T1, T2, T3), Audited(T1), Audited(T2), Audited(T3).
